// План specs/invoices.md 6.1 (#126f07). PROD, admin, компания «test», десктоп, EN.
// @writes @data: счёт (клиент QA-unit client, позиция «QA-AUTO 126f07 item …» $1) → сразу Invoices из меню (без перезагрузки):
// ни разу не показывается «Total Invoices 0» / «No invoices found», созданный счёт в списке. Очистка — Actions → Delete.
// Источник: «מה רצוי» — רשימת Invoices מציגה מיד את כל החשבוניות, כולל החשבונית שנוצרה הרגע, בלי רענון.
// Факты 17.11: «0 в DOM 16–31 мс 2/15, глазом не видно» → принято (решение пользователя: допустимо, если не видно глазом); допуск — кадры < 100 мс.
import { test, expect } from '../../fixtures';
import {
  PROD_CLIENT, PROD_ROLE, addManualItem, openNewInvoiceProd, pickCustomer, prepareProdTest, removeDocumentAt, stamp, waitInvoiceCreated,
} from './invoice-helpers';

test.describe('Invoices list right after creating an invoice (#126f07)', () => {
  test('QA-AUTO: create invoice → Invoices from the menu: no "Total Invoices 0 / No invoices found" for longer than 100 ms, new invoice listed #126f07 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(PROD_ROLE);
    const label = `QA-AUTO 126f07 item ${stamp()}`;
    let url: string | null = null;
    try {
      await prepareProdTest(page);
      await openNewInvoiceProd(page);
      await pickCustomer(page, PROD_CLIENT);
      await addManualItem(page, { name: label, price: '1' });
      await page.getByRole('button', { name: 'Create Invoice' }).click();
      const created = await waitInvoiceCreated(page);
      url = created.url;

      // Наблюдатель: сколько мс на экране «No invoices found» / «Total Invoices 0» после перехода (SPA, без перезагрузки)
      await page.evaluate(() => {
        const w = window as unknown as { __qaEmpty: { since: number | null; worst: number } };
        w.__qaEmpty = { since: null, worst: 0 };
        const scan = () => {
          const t = document.body.innerText;
          const empty = /No invoices found/.test(t) || /Total Invoices\s*\n?\s*0\b/.test(t);
          const now = performance.now();
          if (empty && w.__qaEmpty.since === null) w.__qaEmpty.since = now;
          if (!empty && w.__qaEmpty.since !== null) { w.__qaEmpty.worst = Math.max(w.__qaEmpty.worst, now - w.__qaEmpty.since); w.__qaEmpty.since = null; }
        };
        new MutationObserver(scan).observe(document, { childList: true, subtree: true, characterData: true });
      });
      await page.getByRole('link', { name: 'Invoices', exact: true }).filter({ visible: true }).first().click();
      await page.waitForURL(/\/invoices/i);
      await expect(page.getByRole('button', { name: created.number, exact: true }), 'созданный счёт в списке без перезагрузки').toBeVisible({ timeout: 30_000 });

      const worst = await page.evaluate(() => {
        const e = (window as unknown as { __qaEmpty: { since: number | null; worst: number } }).__qaEmpty;
        return e.since !== null ? Infinity : e.worst;
      });
      expect(worst, '«No invoices found / Total Invoices 0» не видно глазом (< 100 мс)').toBeLessThan(100);
    } finally {
      await removeDocumentAt(page, url, label);
    }
  });
});
